'ob.new_from_ticket' => 'Пропозиція',
'ob.no_offers_vessel' => 'На цьому судні ще немає пропозицій.',
'ob.texts_title' => 'Тексти пропозицій',
'ob.texts_lede' => 'Текстові блоки документа пропозиції — вступ, обсяг, винятки, термін дії, ціни та оплата, умови, завершення — за макетом, мовою, філією та клієнтом. Копіюються в кожну нову пропозицію, де їх можна редагувати.',
'ob.texts_none' => 'Шаблонів ще немає — діють вбудовані тексти. Додайте кнопками праворуч.',
'ob.block' => 'Блок',
'ob.texts_resolve' => 'Який шаблон діє: найспецифічніший активний — клієнт, потім філія, потім мова, потім макет; шаблон, прив’язаний до іншого клієнта, філії, мови чи макета, ніколи не використовується. Мова — та, що в облікових записів порталу клієнта.',
'ob.text_name_ph' => 'напр. Умови — італійська філія',
'ob.any_layout' => '— будь-який макет —',
'ob.builtin_of' => 'Вбудований текст',
'ob.texts_order' => 'Порядок у документі: Вступ · Обсяг · Ціни (таблиця) · Винятки · Термін дії · Ціни та оплата · Умови · Завершення. Порожній блок не друкується.',
'ob.d_intro' => "Шановні панове,\n\nДякуємо за ваш запит. У продовження нашої розмови з радістю подаємо нашу пропозицію {no} для {vessel}, деталізовану нижче.",
'ob.d_scope' => 'Пропозиція охоплює послуги та постачання, перелічені в таблиці цін. Роботи виконують кваліфіковані інженери Golden A/S згідно з інструкціями виробників, чинними вимогами класу та прапора і Загальними умовами надання послуг Golden A/S.',
'ob.d_scope_system' => 'Пропозиція охоплює проєктування, постачання, нагляд за монтажем, введення в експлуатацію та документацію системи, описаної в таблиці цін, згідно з інструкціями виробників, чинними вимогами класу та прапора і Загальними умовами надання послуг Golden A/S.',
'ob.d_scope_remote' => 'Пропозиція охоплює послуги, обладнання та плани віддаленої підтримки, перелічені в таблиці цін, за програмою Remote Support & AR — OceanOpulence™, згідно із Загальними умовами надання послуг Golden A/S.',
'ob.d_exclusions' => 'Якщо не зазначено в таблиці цін, не включено: запчастини та матеріали; проїзд, проживання та добові (за тарифами Golden A/S); збори класу, прапора та порту; роботу поза нормальним робочим часом; затримки поза контролем Golden A/S.',
'ob.d_validity' => 'Ця пропозиція дійсна {validity_days} днів, до {valid_until}.',
'ob.d_payment' => 'Ціни в {currency}, без ПДВ, де застосовно. Погодинні послуги виставляються за фактично відпрацьовані години згідно з доданими тарифами, з мінімальними нарахуваннями тарифної картки; фіксовані ціни — як зазначено. Оплата банківським переказом або кредитною карткою згідно з нашими Загальними умовами надання послуг.',
'ob.d_terms' => 'Понаднормові денні та погодинні тарифи застосовуються в суботу, неділю, свята та понад вісім (8) годин з понеділка по п’ятницю в Греції або десять (10) годин за кордоном та на грецьких островах. Час у дорозі, фіксовані добові, кілометраж і витрати на проїзд — за тарифами Golden A/S {rate_list}. У визначених ремонтних зонах Греції стягується державний збір 180,00 € за дозвіл на роботу.',
'ob.d_closing' => "Сподіваємося, що викладене відповідає вашим вимогам, і залишаємося до ваших послуг для будь-яких уточнень.\n\nЗ повагою,\n{user}\n{branch}",
