'et.k_welcome' => 'Вітання — перше підключення (облікові записи порталу)',
'et.d_s_welcome' => 'Ваш доступ до порталу Golden A/S',
'et.d_b_welcome' => "Шановний/а {name},\n\nВаш обліковий запис на порталі Golden A/S готовий. Будь ласка, виконайте ці три кроки.\n\n1. ПЕРШИЙ ВХІД\n   Відкрийте {url} і увійдіть з вашою електронною адресою {email} та тимчасовим паролем, який ми надаємо окремо (телефоном або другим повідомленням — ніколи в цьому листі).\n\n2. ЗМІНА ПАРОЛЯ\n   Після першого входу натисніть свій аватар угорі праворуч (Мій обліковий запис) і встановіть власний пароль у полі Новий пароль: не менше 10 символів, що не використовується деінде.\n\n3. УВІМКНЕННЯ ДВОФАКТОРНОЇ АВТЕНТИФІКАЦІЇ (2FA)\n   У Мій обліковий запис › Двофакторна автентифікація проскануйте QR-код застосунком authenticator (Microsoft Authenticator, Google Authenticator, Authy, …) і введіть 6-значний код для підтвердження. Відтоді кожен вхід вимагатиме також код із застосунку.\n\nП'ять неправильних паролів блокують обліковий запис на 15 хвилин; якщо ви не можете увійти, дайте відповідь на цей лист — ми розблокуємо його або скинемо пароль.\n\n{signature}",
'au.locked' => 'Заблоковано',
'au.locked_until' => 'Заблоковано до {d} після надто багатьох неправильних паролів',
