'au.welcome' => 'Вітальний лист',
'au.welcome_hint' => 'Відкриває поштову програму з інструкціями першого підключення для цієї особи (вхід, зміна пароля, увімкнення 2FA) — її мовою.',
'au.welcome_lede' => '✉ Вітальний лист відкриває готове повідомлення з інструкціями першого підключення (адреса, зміна пароля, 2FA) для особи. Тимчасовий пароль надсилайте окремо, ніколи в тому ж листі.',
