'eng.rules' => 'Виконано % = (вага завершених результатів робіт + списані години на відкриту роботу, з обмеженням) ÷ (бюджет + затверджені додаткові). Використано % = списано ÷ бюджет — понад 100 % розділ перевищує погоджений бюджет; заштрихована частина смуги — затверджені додаткові години. На 90 % дозволених годин розділ стає жовтогарячим; понад них він перевищений, і нові інженерні години блокуються, доки не буде затверджено додаткові години або розділ не буде оголошено завершеним.',
