'eng.settings' => 'Розділи етапів',
'eng.settings_lede' => 'Розділи технологічної лінії з бюджетом у годинах — Інженерія (Електрика, Автоматизація, Механіка, UI/UX, IT), Виробництво, Об\'єкт і монтаж, HAT / SAT, Пусконалагодження — та дисципліни, що їх живлять. Бюджет розділу — це бюджетні години його дисциплін у Бюджет і факт підпроєкту; його фактичні години — години тих самих дисциплін, зареєстровані на цьому етапі. Одне джерело — погоджене із замовником; затверджені додаткові години показуються над ним і ніколи не додаються до нього.',
'eng.map_title' => 'Матриця дисципліна × розділ',
'eng.map_hint' => 'Позначте розділи, які живить кожна дисципліна. Інженерні дисципліни живлять один інженерний розділ; монтажник живить Об\'єкт і монтаж та HAT / SAT; сервісний інженер або інженер з автоматизації — HAT / SAT і Пусконалагодження. Дисципліна, що живить кілька розділів, отримує одну комірку бюджету на розділ у Бюджет і факт, а етап, обраний у рядку табеля, визначає, де зараховуються її години. Дисципліни керівництва та продажів залишаються без прив\'язки.',
'eng.map_none' => '— не інженерія',
'eng.map_save_hint' => 'Застосовується до кожного підпроєкту негайно (бюджети, факт і етап «Інженерія» перераховуються за відповідністю).',
'eng.sec_title' => 'Розділи',
